sections.css:
.liquid-obsidian{background: var(--surface-base); backdrop-filter: blur(40px) saturate(180%); box-shadow: inset 0 1px 1px var(--surface-highlight),
    inset 0 -2px 10px rgba(0, 0, 0, 0.4),
    0 30px 60px rgba(0, 0, 0, 0.4); border-radius: 2rem; position: relative; isolation: isolate;}
.liquid-obsidian::before{content: ""; position: absolute; inset: 0px; border-radius: inherit; padding: 1px; background: radial-gradient(
    800px circle at var(--mouse-x) var(--mouse-y),
    var(--nebula-blue),
    transparent 40%
  ); mask: linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px) content-box exclude, linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px); opacity: 0.3; pointer-events: none; transition: opacity 0.5s;}
.liquid-obsidian:hover::before{opacity: 1;}
.frosted-ether{background: radial-gradient(circle at top left, var(--surface-highlight), transparent 70%); backdrop-filter: blur(60px); box-shadow: rgba(255, 255, 255, 0.1) 0px 2px 4px inset, rgba(0, 0, 0, 0.5) 0px -2px 20px inset, rgba(0, 0, 0, 0.3) 0px 15px 35px; border-radius: 1.5rem; position: relative; overflow: hidden;}
.reveal-scroll{opacity: 0; transform: translateY(40px) scale(0.98); filter: blur(10px); animation-duration: auto; animation-timing-function: linear; animation-delay: 0s; animation-iteration-count: 1; animation-direction: normal; animation-fill-mode: forwards; animation-play-state: running; animation-name: reveal-keyframe; animation-timeline: view(); animation-range: entry 10% cover 30%;}
.bento-grid{container: bento / inline-size;}
.micro-label{font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.3em; color: var(--text-muted); font-weight: 500;}
h2, h3{font-size: inherit; font-weight: inherit;}
h2, h3, p{margin: 0px;}
.pointer-events-none{pointer-events: none;}
.absolute{position: absolute;}
.relative{position: relative;}
.inset-0{inset: 0px;}
.-right-20{right: -5rem;}
.-top-20{top: -5rem;}
.z-10{z-index: 10;}
.mb-2{margin-bottom: 0.5rem;}
.mb-4{margin-bottom: 1rem;}
.mb-6{margin-bottom: 1.5rem;}
.ml-1{margin-left: 0.25rem;}
.mt-12{margin-top: 3rem;}
.mt-24{margin-top: 6rem;}
.mt-auto{margin-top: auto;}
.flex{display: flex;}
.grid{display: grid;}
.h-1{height: 0.25rem;}
.h-3{height: 0.75rem;}
.h-64{height: 16rem;}
.h-full{height: 100%;}
.w-1\/2{width: 50%;}
.w-1\/4{width: 25%;}
.w-3{width: 0.75rem;}
.w-64{width: 16rem;}
.max-w-lg{max-width: 32rem;}
.origin-left{transform-origin: left center;}
.grid-cols-1{grid-template-columns: repeat(1, minmax(0px, 1fr));}
.flex-col{flex-direction: column;}
.items-start{align-items: flex-start;}
.items-center{align-items: center;}
.justify-between{justify-content: space-between;}
.gap-4{gap: 1rem;}
.gap-6{gap: 1.5rem;}
.overflow-hidden{overflow: hidden;}
.rounded-full{border-radius: 9999px;}
.bg-\[var\(--cosmic-violet\)\]{background-color: var(--cosmic-violet);}
.bg-\[var\(--nebula-blue\)\]{background-color: var(--nebula-blue);}
.bg-gradient-to-r{background-image: linear-gradient(to right, var(--tw-gradient-stops));}
.p-10{padding: 2.5rem;}
.text-2xl{font-size: 1.5rem; line-height: 2rem;}
.text-3xl{font-size: 1.875rem; line-height: 2.25rem;}
.text-4xl{font-size: 2.25rem; line-height: 2.5rem;}
.text-6xl{font-size: 3.75rem; line-height: 1;}
.text-lg{font-size: 1.125rem; line-height: 1.75rem;}
.text-sm{font-size: 0.875rem; line-height: 1.25rem;}
.font-light{font-weight: 300;}
.leading-relaxed{line-height: 1.625;}
.leading-tight{line-height: 1.25;}
.tracking-tight{letter-spacing: -0.025em;}
.tracking-tighter{letter-spacing: -0.05em;}
.text-\[var\(--text-muted\)\]{color: var(--text-muted);}
.text-\[var\(--text-primary\)\]{color: var(--text-primary);}
.opacity-40{opacity: 0.4;}
.opacity-50{opacity: 0.5;}
.mix-blend-screen{mix-blend-mode: screen;}
.mix-blend-overlay{mix-blend-mode: overlay;}
.shadow-\[0_0_15px_var\(--cosmic-violet\)\]{--tw-shadow: 0 0 15px var(--cosmic-violet); --tw-shadow-colored: 0 0 15px var(--tw-shadow-color); box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);}
.shadow-\[0_0_15px_var\(--nebula-blue\)\]{--tw-shadow: 0 0 15px var(--nebula-blue); --tw-shadow-colored: 0 0 15px var(--tw-shadow-color); box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);}
.shadow-\[0_0_20px_var\(--nebula-blue\)\]{--tw-shadow: 0 0 20px var(--nebula-blue); --tw-shadow-colored: 0 0 20px var(--tw-shadow-color); box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);}
.blur-\[80px\]{--tw-blur: blur(80px); filter: var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow);}
.filter{filter: var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow);}
.transition-transform{transition-property: transform; transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1); transition-duration: 150ms;}
.duration-700{transition-duration: 700ms;}
.group:hover .group-hover\:scale-105{--tw-scale-x: 1.05; --tw-scale-y: 1.05; transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));}
@media (min-width: 768px){.md\:col-span-4{grid-column: span 4 / span 4;}}
@media (min-width: 768px){.md\:col-span-5{grid-column: span 5 / span 5;}}
@media (min-width: 768px){.md\:col-span-7{grid-column: span 7 / span 7;}}
@media (min-width: 768px){.md\:col-span-8{grid-column: span 8 / span 8;}}
@media (min-width: 768px){.md\:grid-cols-12{grid-template-columns: repeat(12, minmax(0px, 1fr));}}
@media (min-width: 768px){.md\:p-16{padding: 4rem;}}
@media (min-width: 768px){.md\:text-5xl{font-size: 3rem; line-height: 1;}}
@media (min-width: 768px){.md\:text-7xl{font-size: 4.5rem; line-height: 1;}}
